INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist dhclient das einzige Tool für DHCP?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt auch dhcpcd und mehr"}, {"text": "Ja", "correct": false, "because": "Mehrere Tools existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat dhclient im Netzwerk?', 3, '[{"text": "IP-Adressen anfragen", "correct": true, "because": "Holt Konfiguration vom Server"}, {"text": "Paketverlust messen", "correct": false, "because": "Ping-spezifisch"}, {"text": "Routing verwalten", "correct": false, "because": "Router-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten DHCP-Tools?', 5, '[{"text": "Adresszuweisung", "correct": true, "because": "dhclient holt IPs"}, {"text": "Netzwerküberwachung", "correct": true, "because": "Tools wie Wireshark"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht DHCP"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) dhclient nutzt Broadcast. b) Es ist nur für IPv6.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch IPv4 unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei DHCP-Tools?', 4, '[{"text": "DHCP-Anfragen", "correct": false, "because": "Kernfunktion"}, {"text": "Netzwerkverkehr", "correct": false, "because": "Überwachungsziel"}, {"text": "Webserver-Logs", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob dhclient automatisch startet?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch bei Boot"}, {"text": "Nein", "correct": false, "because": "Oft Systemkonfig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool überwacht DHCP-Verkehr?', 3, '[{"text": "Wireshark", "correct": true, "because": "Analysiert Pakete"}, {"text": "dhclient", "correct": false, "because": "Nur Client"}, {"text": "ping", "correct": false, "because": "Erreichbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten DHCP-Tools?', 5, '[{"text": "Automatische IPs", "correct": true, "because": "dhclient vereinfacht"}, {"text": "Verkehrsanalyse", "correct": true, "because": "z. B. Wireshark"}, {"text": "Routing-Optimierung", "correct": false, "because": "Router-Aufgabe"}, {"text": "Bandbreitensteigerung", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) dhclient holt IP-Adressen. b) Es überwacht Netzwerke. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überwachung nicht dhclient"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DHCP-Tools?', 4, '[{"text": "Netzwerkadapter", "correct": false, "because": "Für Kommunikation nötig"}, {"text": "DHCP-Server", "correct": false, "because": "Liefert IPs"}, {"text": "Web-UI", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist dhclient für Überwachung gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur IP-Anfrage"}, {"text": "Ja", "correct": false, "because": "Andere Tools dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool hilft bei DHCP-Fehleranalyse?', 4, '[{"text": "Wireshark", "correct": true, "because": "Zeigt DHCP-Pakete"}, {"text": "dhclient", "correct": false, "because": "Nur Client"}, {"text": "ifconfig", "correct": false, "because": "Nur Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DHCP-Tools nur IPs zuweisen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Überwachung möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei DHCP-Tools?', 3, '[{"text": "IP-Zuweisung", "correct": true, "because": "Kernfunktion"}, {"text": "DNS-Konfig", "correct": false, "because": "Sekundär"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) dhclient fragt DHCP-Server. b) Es ersetzt Wireshark.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wireshark ist Analyse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben DHCP-Tools?', 5, '[{"text": "Automatisierung", "correct": true, "because": "IP-Zuweisung"}, {"text": "Diagnosefähigkeit", "correct": true, "because": "Überwachung"}, {"text": "Routing", "correct": false, "because": "Router-Aufgabe"}, {"text": "Verschlüsselung", "correct": false, "because": "Nicht DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DHCP-Tools unwichtig?', 3, '[{"text": "Broadcast", "correct": false, "because": "Für Anfragen nötig"}, {"text": "Netzwerkadapter", "correct": false, "because": "Kommunikation"}, {"text": "HTTP-Port", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann dhclient Netzwerke überwachen?', 3, '[{"text": "Nein", "correct": true, "because": "Nur IP-Anfrage"}, {"text": "Ja", "correct": false, "because": "Andere Tools dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DHCP-Tools Paketverlust messen?', 2, '[{"text": "Nein", "correct": true, "because": "Ping-Aufgabe"}, {"text": "Ja", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool zeigt DHCP-Pakete detailliert?', 4, '[{"text": "Wireshark", "correct": true, "because": "Analyse-Tool"}, {"text": "dhclient", "correct": false, "because": "Nur Client"}, {"text": "traceroute", "correct": false, "because": "Pfadanalyse"}]');
